PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users(email TEXT PRIMARY KEY,password TEXT);
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY,email TEXT NOT NULL REFERENCES users(email),csrf TEXT NOT NULL,expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS challenges(id TEXT PRIMARY KEY,email TEXT NOT NULL,purpose TEXT NOT NULL,code TEXT NOT NULL,expires INTEGER NOT NULL,attempts INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS instances(id TEXT PRIMARY KEY,name TEXT NOT NULL,owner TEXT NOT NULL REFERENCES users(email),device TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS grants(instance TEXT NOT NULL REFERENCES instances(id) ON DELETE CASCADE,email TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('owner','operator','observer')),PRIMARY KEY(instance,email));
CREATE TABLE IF NOT EXISTS enrollments(id TEXT PRIMARY KEY,name TEXT NOT NULL,email TEXT NOT NULL,claim TEXT NOT NULL,challenge TEXT NOT NULL REFERENCES challenges(id),expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS outbox(id INTEGER PRIMARY KEY AUTOINCREMENT,email TEXT NOT NULL,body TEXT NOT NULL,expires INTEGER NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,next_attempt INTEGER NOT NULL DEFAULT 0,sent INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY AUTOINCREMENT,at INTEGER NOT NULL,actor TEXT NOT NULL,action TEXT NOT NULL,instance TEXT);
CREATE TABLE IF NOT EXISTS preferences(email TEXT PRIMARY KEY REFERENCES users(email),value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS tickets(token TEXT PRIMARY KEY,session TEXT NOT NULL,instance TEXT NOT NULL,version INTEGER NOT NULL,expires INTEGER NOT NULL);
